#!/usr/bin/env bash
# lib/sign-module.sh
# sign_module <path.ko>
#
# Signs an out-of-tree module with the signing key generated by the kernel
# build and verifies the signature was actually appended.
#
# Requires (set by the caller, see build.sh):
#   KSRC   kernel build output directory (the O= dir)
#   WORKDIR scratch directory containing kernel-src/
#   ARCH   target architecture (arm64)
#
# Why this exists: CONFIG_MODULE_SIG_ALL only signs modules during
# modules_install, which Android flashable zips never run, and
# CONFIG_MODULE_SIG_FORCE=y rejects unsigned modules at insmod time.
# See docs/SIGNING.md for the full story.
sign_module() {
  local ko="$1"
  if [ ! -x "$KSRC/scripts/sign-file" ]; then
    echo "[*] building scripts (sign-file)"
    make -C "$WORKDIR/kernel-src" O="$KSRC" ARCH="$ARCH" scripts
  fi
  "$KSRC/scripts/sign-file" sha512 \
    "$KSRC/certs/signing_key.pem" \
    "$KSRC/certs/signing_key.x509" \
    "$ko"
  tail -c 4096 "$ko" | grep -aq "Module signature appended" \
    || { echo "ERROR: module signature missing on $ko" >&2; exit 1; }
  echo "[*] signed: $(basename "$ko")"
}
